UPDATE TB_EEP_BATCH_ICAL_M SET
	  ICAL_NM = #{ICAL_NM}
	, ICAL_URL = COALESCE(NULLIF(#{ICAL_URL}, ''), ICAL_URL)
	, DRIVE_FOLDER_ID = COALESCE(#{DRIVE_FOLDER_ID}, DRIVE_FOLDER_ID)
WHERE ICAL_SQ = #{ICAL_SQ}

